// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != c.owner());
        vm.assume(amount > 0 && amount <= address(this).balance);
        vm.deal(address(this), amount);
        Reverter reverter = new Reverter();
        vm.prank(actor);
        bool ok = true;
        try c.sendMoney(address(reverter), amount) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "sendMoney as non-owner should revert");
    }
}

contract Reverter { fallback() external payable { revert(); } }
